CREATE TABLE `practice_rounds` (
	`id` text PRIMARY KEY NOT NULL,
	`user_id` text NOT NULL,
	`number` integer NOT NULL,
	`created_at` integer NOT NULL,
	`active` integer DEFAULT 0 NOT NULL,
	`idempotency_key` text,
	CONSTRAINT "practice_round_positive" CHECK("practice_rounds"."number">0),
	CONSTRAINT "practice_round_boolean" CHECK("practice_rounds"."active" IN (0,1))
);
--> statement-breakpoint
CREATE UNIQUE INDEX `practice_round_user_number` ON `practice_rounds` (`user_id`,`number`);--> statement-breakpoint
CREATE UNIQUE INDEX `practice_round_request` ON `practice_rounds` (`user_id`,`idempotency_key`);--> statement-breakpoint
CREATE UNIQUE INDEX `practice_round_active` ON `practice_rounds` (`user_id`) WHERE "practice_rounds"."active"=1;--> statement-breakpoint
ALTER TABLE `submissions` ADD `practice_round_id` text REFERENCES practice_rounds(id);--> statement-breakpoint
CREATE INDEX `submission_round_progress` ON `submissions` (`user_id`,`practice_round_id`,`mode`,`status`,`problem_id`);
--> statement-breakpoint
